<template><PageScroller :loading="loading" @refresh="load(true)" @load-more="load()"><view class="toolbar"><view class="tabs"><text :class="filter==='all'?'active':''" @click="changeFilter('all')">全部</text><text :class="filter==='unread'?'active':''" @click="changeFilter('unread')">未读</text></view><text class="read-all" @click="markAll">全部已读</text></view><view class="list"><view v-for="item in items" :key="item.id" class="card message" :class="!item.readFlag?'unread':''" @click="open(item)"><view class="card__top"><view class="title-wrap"><text v-if="!item.readFlag" class="dot"/><text class="card__title">{{item.title}}</text></view><text class="status" :class="statusClass(item.alarmStatus)">{{statusText(item.alarmStatus)}}</text></view><text class="card__meta">{{item.content||''}}\n{{item.createTime}}</text></view><EmptyState v-if="!loading&&!items.length" title="暂无消息" description="告警和系统通知会显示在这里"/><view v-if="items.length" class="footer">{{loading?'加载中…':finished?'没有更多了':'继续上滑加载更多'}}</view></view></PageScroller></template>
<script setup lang="ts">
import{ref}from'vue';import{onShow}from'@dcloudio/uni-app';import PageScroller from'@/components/PageScroller.vue';import EmptyState from'@/components/EmptyState.vue';import{queryMessages,readMessage,readAllMessages,type SystemMessage}from'@/api/message';import{showRequestError}from'@/utils/request';import{refreshMessageBadge}from'@/utils/message-badge';import{useAuthStore}from'@/stores/auth';const auth=useAuthStore(),filter=ref<'all'|'unread'>('all'),items=ref<SystemMessage[]>([]),page=ref(1),loading=ref(false),finished=ref(false);async function load(reset=false){if(loading.value||(!reset&&finished.value))return;if(reset){page.value=1;finished.value=false}loading.value=true;try{const params:Record<string,unknown>={page:page.value,count:20};if(filter.value==='unread')params.readFlag=false;const r=await queryMessages(params);const list=r.list||r.items||[];items.value=reset?list:[...items.value,...list];finished.value=list.length<20;page.value++}catch(e){showRequestError(e)}finally{loading.value=false}}function changeFilter(v:'all'|'unread'){filter.value=v;load(true)}async function open(i:SystemMessage){if(!i.readFlag){await readMessage(i.id);i.readFlag=true;refreshMessageBadge()}if(i.businessType==='DEVICE_ALARM'&&i.businessId)uni.navigateTo({url:`/pages/alarm/detail?id=${i.businessId}`})}async function markAll(){try{await readAllMessages();items.value.forEach(i=>i.readFlag=true);refreshMessageBadge();uni.showToast({title:'已全部标为已读',icon:'none'})}catch(e){showRequestError(e)}}function statusText(s?:string){return({PENDING:'待处理',ACKNOWLEDGED:'已确认',RESOLVED:'已处理',FALSE_ALARM:'误报'}as Record<string,string>)[s||'']||'通知'}function statusClass(s?:string){return s==='PENDING'?'pending':s==='RESOLVED'?'resolved':'normal'}onShow(()=>{if(auth.requireAuth()){load(true);refreshMessageBadge()}})
</script><style lang="scss" scoped>@use '@/styles/list.scss';.toolbar{display:flex;align-items:center;justify-content:space-between;padding:22rpx 28rpx;background:#fff}.tabs{display:flex;gap:36rpx;color:#8992a6;font-size:27rpx}.tabs .active{color:#2368f2;font-weight:600}.read-all{color:#2368f2;font-size:24rpx}.message{position:relative}.unread{background:#f8fbff}.title-wrap{min-width:0;display:flex;align-items:center;gap:12rpx;flex:1}.dot{width:14rpx;height:14rpx;flex:none;background:#e5484d;border-radius:50%}.status{padding:6rpx 14rpx;border-radius:999rpx;font-size:21rpx}.pending{color:#b54708;background:#ffead5}.resolved{color:#14804a;background:#e4f7ed}.normal{color:#475467;background:#edf0f5}</style>
